#!/usr/bin/env python3
"""Apply script: target premium input + dynamic existing/quote category mapping.
Run from the HealthCross repo root: python3 apply_target_premium_and_category_mapping.py
Each file is self-checksummed (SHA256) so a silent partial-write is caught
immediately rather than discovered later - see MARKER below.
"""
import base64, hashlib, os, sys

MARKER = "TARGET_PREMIUM_CATEGORY_MAPPING_2026_08_04"

FILES = [
    {
        'path': 'app/api/routes_analysis.py',
        'sha256': '12f00718b1b9578e8770ba0f4760ec89fc9a4811ce1db78951febbf7636b2ab3',
        'size': 40148,
        'b64': '',
    },
    {
        'path': 'app/api/routes_cases.py',
        'sha256': '63484771ceacaf46ba2c6e44f5a7ee0bc235c93816265fd6acfc33ef7db6e7c1',
        'size': 26515,
        'b64': '',
    },
    {
        'path': 'app/models/db_models.py',
        'sha256': '3920572153852a67657073c464937dd14df88e6cc546141828563bf611c6982d',
        'size': 28256,
        'b64': '',
    },
    {
        'path': 'app/models/schemas.py',
        'sha256': 'af3cd7d6b9f1ff774c610d8afdc2ca34f57b80a131330c7ebf730df8598251c2',
        'size': 13117,
        'b64': '',
    },
    {
        'path': 'app/static/index.html',
        'sha256': '7334a8557c3d2841a04f6e17be1fd8e0c99ee41f4628467180e4d7afe7ae91a3',
        'size': 138384,
        'b64': '',
    },
    {
        'path': 'tests/test_api_quote_and_comparison.py',
        'sha256': '47532ea8ed3f8f42472fd43c1fa7e29bec54c51501d2b7cb260b9d6a04ddf23a',
        'size': 13073,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 440 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
